practice.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SimpleStorage {
    uint256 public favorite;

    function set(uint256 x) external {
        favorite = x;
    }

    function get() external view returns (uint256) {
        return favorite;
    }

    function reset() external {
        favorite = 0;
    }
}

