mastery.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Counter {
    uint256 public count;

    function increment() external {
        count += 1;
    }

    function decrement() external {
        count -= 1; // reverts (Panic 0x11) bij 0 dankzij checked arithmetic
    }
}

