production.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// Een gastenboek op de blockchain.
contract Guestbook {
    string public lastMessage;
    address public lastSigner;
    uint256 public signatures;

    function sign(string calldata message) external {
        lastMessage = message;
        lastSigner = msg.sender;
        signatures += 1;
    }
}
